import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  时间: z.object({
    日期: z.string().prefault('05-20'),
    星期: z.enum(['周一', '周二', '周三', '周四', '周五', '周六', '周日']).prefault('周一'),
    时刻: z.string().prefault('10:00'),
    餐馆状态: z.enum(['营业', '休息', '准备']).prefault('休息'),
  }).prefault({}),

  种族好感度: z.record(
    z.enum(['凛原族', '酿林族', '香丘族', '醉溪族', '浅漪族', '云翎族', '炎羽族', '霜翎族', '渊珠族', '礁珀族', '泥甲族', '荇须族']),
    z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0)
  ).prefault({}),

  个人好感度: z.record(
    z.string().describe('兽娘名'),
    z.object({
      种族: z.enum(['凛原族', '酿林族', '香丘族', '醉溪族', '浅漪族', '云翎族', '炎羽族', '霜翎族', '渊珠族', '礁珀族', '泥甲族', '荇须族']),
      好感度: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
      状态: z.string().prefault('正常'),
    })
  ).prefault({}),
});

$(() => {
  registerMvuSchema(Schema);
})

