  <script type="module">
    function toggleSection(header) {
      const content = header.next('.section-content');
      const arrow = header.find('.section-arrow');
      if (content.hasClass('hidden')) {
        content.removeClass('hidden');
        arrow.removeClass('collapsed');
      } else {
        content.addClass('hidden');
        arrow.addClass('collapsed');
      }
    }

    function populateData() {
      const all_vars = getAllVariables();
      const data = _.get(all_vars, 'stat_data', {});

      /* 时间 */
      const date = _.get(data, '时间.日期', '--');
      const weekday = _.get(data, '时间.星期', '--');
      const time = _.get(data, '时间.时刻', '--:--');
      const restaurant = _.get(data, '时间.餐馆状态', '--');
      $('#time-date').text(date);
      $('#time-weekday').text(weekday);
      $('#time-clock').text(time);
      $('#time-status').text(restaurant);

      /* 种族好感度 */
      const race_map = [
        { key: '凛原族', cls: 'linran' },
        { key: '酿林族', cls: 'nianglin' },
        { key: '香丘族', cls: 'xiangqiu' },
        { key: '醉溪族', cls: 'zuixi' },
        { key: '浅漪族', cls: 'qianyi' },
        { key: '云翎族', cls: 'yunling' },
        { key: '炎羽族', cls: 'yanyu' },
        { key: '霜翎族', cls: 'shuangling' },
        { key: '渊珠族', cls: 'yuanzhu' },
        { key: '礁珀族', cls: 'jiangpo' },
        { key: '泥甲族', cls: 'nijia' },
        { key: '荇须族', cls: 'xingxu' }
      ];

      const race_container = $('#race-grid');
      race_container.empty();

      race_map.forEach(function(race) {
        const val = _.get(data, '种族好感度.' + race.key, 0);
        const num_val = typeof val === 'number' ? val : 0;
        const item = $(
          '<div class="race-item">' +
            '<span class="race-dot dot-' + race.cls + '"></span>' +
            '<span class="race-name">' + race.key + '</span>' +
            '<div class="race-bar-bg">' +
              '<div class="race-bar-fill color-' + race.cls + '" style="width: ' + num_val + '%"></div>' +
            '</div>' +
            '<span class="race-value">' + num_val + '</span>' +
          '</div>'
        );
        race_container.append(item);
      });

      /* 个人好感度 */
      const persons = _.get(data, '个人好感度', {});
      const person_container = $('#person-list');
      person_container.empty();

      const person_entries = Object.entries(persons);

      if (person_entries.length === 0) {
        person_container.html('<div class="no-data">尚无跟随者</div>');
      } else {
        person_entries.forEach(function(entry) {
          const name = entry[0];
          const info = entry[1];
          const race_key = _.get(info, '种族', '');
          const fav = _.get(info, '好感度', 0);
          const status = _.get(info, '状态', '');
          const num_fav = typeof fav === 'number' ? fav : 0;

          const race_match = race_map.find(function(r) { return r.key === race_key; });
          const tag_cls = race_match ? 'tag-' + race_match.cls : '';
          const bar_cls = race_match ? 'color-' + race_match.cls : 'color-linran';
          const card_cls = race_match ? 'person-card-' + race_match.cls : '';

          const card = $(
            '<div class="person-card ' + card_cls + '">' +
              '<span class="person-race-tag ' + tag_cls + '">' + race_key + '</span>' +
              '<div class="person-info">' +
                '<div><span class="person-name">' + name + '</span><span class="person-status">' + status + '</span></div>' +
                '<div class="person-bar-bg"><div class="person-bar-fill ' + bar_cls + '" style="width: ' + num_fav + '%"></div></div>' +
              '</div>' +
              '<span class="person-value">' + num_fav + '</span>' +
            '</div>'
          );
          person_container.append(card);
        });
      }
    }

