  <script type="module">
    function getAffClass(val) {
      if (val >= 80) return 'aff-max';
      if (val >= 50) return 'aff-high';
      if (val >= 20) return 'aff-mid';
      return 'aff-low';
    }

    function getRaceIcon(race) {
      const icons = {
        '凛原族': '🦬',
        '酿林族': '🐝',
        '香丘族': '🐐',
        '醉溪族': '🍺',
        '浅漪族': '🦆',
        '云翎族': '🦅',
        '炎羽族': '🔥',
        '霜翎族': '❄️',
        '渊珠族': '🐟',
        '礁珀族': '🦪',
        '泥甲族': '🦀',
        '荇须族': '🦐'
      };
      return icons[race] || '🐾';
    }

    function toggleSection($header) {
      const $content = $header.next('.section-content');
      $header.toggleClass('collapsed');
      $content.toggleClass('collapsed');
    }

    function populateRaceGrid(data) {
      const $grid = $('#race-grid');
      $grid.empty();

      const raceNames = [
        '凛原族', '酿林族', '香丘族', '醉溪族',
        '浅漪族', '云翎族', '炎羽族', '霜翎族',
        '渊珠族', '礁珀族', '泥甲族', '荇须族'
      ];

      raceNames.forEach(race => {
        const val = _.get(data, race, 0);
        const icon = getRaceIcon(race);
        const cls = getAffClass(val);

        const $item = $(`
          <div class="race-item">
            <span class="race-name">${icon} ${race}</span>
            <div class="race-bar-wrap">
              <div class="race-bar ${cls}" style="width: ${val}%"></div>
            </div>
            <span class="race-val">${val}</span>
          </div>
        `);
        $grid.append($item);
      });
    }

    function populatePersonalList(data) {
      const $list = $('#personal-list');
      $list.empty();

      const entries = Object.entries(data);

      if (entries.length === 0) {
        $list.html('<div class="empty-hint">尚未结识任何兽娘</div>');
        return;
      }

      entries.forEach(([name, info]) => {
        const race = _.get(info, '种族', '');
        const val = _.get(info, '好感度', 0);
        const status = _.get(info, '状态', '正常');
        const icon = getRaceIcon(race);
        const cls = getAffClass(val);

        const $card = $(`
          <div class="personal-card">
            <div class="personal-avatar">${icon}</div>
            <div class="personal-info">
              <div class="personal-top">
                <span class="personal-name">${name}</span>
                <span class="personal-race">${race}</span>
                <span class="personal-status">${status}</span>
              </div>
              <div class="personal-bar-wrap">
                <div class="personal-bar ${cls}" style="width: ${val}%"></div>
              </div>
              <div class="personal-bottom">
                <span class="personal-val">${val}</span>
                <span class="personal-label">好感度</span>
              </div>
            </div>
          </div>
        `);
        $list.append($card);
      });
    }

    function populateCharacterData() {
      const all_variables = getAllVariables();
      const stat_data = _.get(all_variables, 'stat_data', {});

      const raceAff = _.get(stat_data, '种族好感度', {});
      const personalAff = _.get(stat_data, '个人好感度', {});

      populateRaceGrid(raceAff);
      populatePersonalList(personalAff);
    }

    function toggleMobileMode() {
      const $board = $('.board');
      const isMobile = $board.hasClass('mobile-mode');
      $board.toggleClass('mobile-mode');

      const $btn = $('.mode-toggle');
      $btn.text(isMobile ? '🖥️' : '📱');
    }

    async function init() {
      await waitGlobalInitialized('Mvu');
      populateCharacterData();

      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
        populateCharacterData();
      });

      $('.section-header').on('click', function () {
        toggleSection($(this));
      });

      $('.mode-toggle').on('click', toggleMobileMode);
    }

    $(errorCatched(init));
  </script>
